end;


function SeparateParenGroups(parenString : string): array of string;
begin
  var openBraces := 0;
  Result := [];
  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = '(' then
      openBraces += 1
    else if parenString[i] = ')' then
      openBraces -= 1
    else if parenString[i] = ' ' then
      continue;
    if openBraces = 0 then
    begin
      var sb := new StringBuilder;
      while (i < parenString.Length) and (parenString[i] <> ' ') do
      begin
        sb.Append(parenString[i]);
        i += 1;
      end;
      Result.Add(sb.ToString);
    end;
  end;
end;


