function ParseNestedParens(parenString: string): array of integer;
begin
  Result := new integer[parenString.Length];
  var i := 0;
  var max := 0;
  foreach var c in parenString.Where(x -> x <> ' ') do
  begin
    if c = '(' then
    begin
      var level := 0;
      Result[i] := level;
      Inc(max);
    end
    else if c = ')' then
    begin
      var level := Result[i - 1];
      Inc(level);
      Result[i] := level;
      Dec(max);
    end;
    Inc(i);
  end;
  for var j := 0 to max - 1 do
    Result[i + j] := 0;
end;


