function IsPalindrome(text: string): boolean;
begin
  var sb := new StringBuilder(text.ToLower);
  if sb.Length > 0 then
    for var i := 0 to sb.Length - 2 do
      if not char.IsLetter(sb[i]) then
        continue;

    for var i := 0 to sb.Length - 2 do
      if not char.IsLetter(sb[sb.Length - 1 - i]) then
        break;

    if sb.Length = 0 then
      Result := True
    else if sb.Length = 1 then
      Result := True
    else if sb[0] = sb[sb.Length - 1] then
      Result := IsPalindrome(sb.Substring(1, sb.Length - 2))
    else Result := False
end;


