function Pluck(arr: array of integer): array of integer;
begin
  var lst := arr.Where(x -> x <> 0).Where(x -> x mod 2 = 0).ToList;
  if lst.Count = 0 then
    Result := []
  else
    Result := new integer[2](lst.Max(x -> x.Value), lst.FindIndex(x -> x.Value = lst.Max(x -> x.Value)));
end;


function Search(lst: array of integer): integer;
begin
  var d := lst.GroupBy(i -> i).ToDictionary(g -> g.Key, g -> g.Count);
  var (i, res) := (0, -1);
  while i <= 2 * lst.Max do
  begin
    if d.ContainsKey(i) then
    begin
      if res < i then
        res := i;
    end;
    i += 1;
  end;
  Result := res;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  var min := integer.MaxValue;
  var res := new integer[lst.Length];
  for var i := 0 to lst.Length - 1 do
  begin
    if lst[i] < min then
      min := lst[i];
    res[i] := min;
  end;
  var max := integer.MinValue;
  for var i := 0 to lst.Length - 1 do
  begin
    if lst[i] > max then
      max := lst[i];
    lst[i] := max;
  end;
  Result := lst;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    var (x, y, z) := (a, b, c);
    Result := Round(Sqrt(x * x + y * y) * Sqrt(y * y + z * z) +
        Sqrt(z * z + x * x) * Sqrt(x * x + y * y), 2);
    exit;
  end;
  Result := -1;
end;


