function IsMultiplyPrime(a: integer): boolean;
begin
  var (p1, p2, p3) := (0, 0, 0);
  var (i, j, k) := (0, 0, 1);
  while Sqr(5) * k <= a do
  begin
    if a mod p1 = 0 then
    begin
      p1 := a div p1;
      Inc(i);
    end;
    if a mod p2 = 0 then
    begin
      p2 := a div p2;
      Inc(j);
    end;
    if a mod p3 = 0 then
    begin
      p3 := a div p3;
      Inc(k);
    end;
    Inc(Sqr(5)*k);
  end;
  Result := (i = 1) and (j = 1) and (k = 1)
end;


