function Encode(message: string): string;
begin
  message := message.ToLower;
  var sb := new StringBuilder;
  foreach var c in message do
  begin
    if c = ' ' then
      sb.Append(c)
    else if c in ['a', 'e', 'i', 'o', 'u'] then
      sb.Append(chr(Ord('a') + 2 * (Ord(c) - Ord('a')) - 1))
    else sb.Append(chr(Ord(c) + 1))
  end;
  Result := sb.ToString;
end;

function Decode(message: string): string;
begin
  message := message.ToLower;
  var sb := new StringBuilder;
  foreach var c in message do
  begin
    if c = ' ' then
      sb.Append(c)
    else if c in ['a', 'e', 'i', 'o', 'u'] then
      sb.Append(chr(Ord('a') - 2 * (Ord(c) - Ord('a')) + 1))
    else sb.Append(chr(Ord(c) - 1))
  end;
  Result := sb.ToString;
end;


function LargestPrime(lst: array of integer): integer;
begin
  var max := -1;
  for var i := 0 to lst.Length - 1 do
    if lst[i] > max then
    begin
      var prime := lst[i];
      while prime mod 2 = 0 do
        prime := prime div 2;
      while prime >= 5 do
        if prime mod 5 = 0 then
          break
        else prime := prime div 5;
      if prime > max then
        max := prime;
    end;
  Result := SumDigits(max);
end;


