function EvenOddPalindrome(n : integer): (integer, integer);
begin
  var count_even := 0;
  var count_odd := 0;
  for var i := 1 to n do
  begin
    var s := i.ToString;
    if s = s.ReverseString then
    begin
      if i mod 2 = 0 then
        count_even += 1;
      else
        count_odd += 1;
    end;
  end;
  Result := (count_even, count_odd)
end;


function CountNums(arr: array of integer): integer;
begin
  Result := 0;
  for var i := 0 to arr.Length - 1 do
  begin
    var absnum := Abs(arr[i]);
    while absnum >= 10 do
    begin
      if absnum mod 10 > 0 then
        Result += 1;
      absnum := absnum div 10
    end;
    if absnum > 0 then
      Result += 1;
  end;
end;


