function Exchange(lst1, lst2 : array of integer): string;
begin
  var (count1, count2) := (0, 0);
  for var i := 0 to lst1.Length - 1 do
    if lst1[i] mod 2 = 0 then
      count1 += 1
    else if lst2[i] mod 2 = 0 then
      count2 += 1
    else Result := 'NO';
  if (count1 = 0) or (count2 = 0) then
    exit
  ;
  var (ex1, ex2) := (0, 0);
  for var i := 0 to lst1.Length - 1 do
    if lst1[i] mod 2 = 0 then
      ex1 += 1
    else if lst2[i] mod 2 = 0 then
      ex2 += 1
    else if lst1[i] <> lst2[i] then
      if (lst1[i] + 1) mod 2 = 0 then
        ex1 += 1
      else if (lst2[i] + 1) mod 2 = 0 then
        ex2 += 1
    else if lst1[i] + 1 <> lst2[i] then
      if (lst1[i] + 1) mod 2 = 0 then
        ex1 += 1
      else if (lst2[i] + 1) mod 2 = 0 then
        ex2 += 1
    else if lst1[i] + 2 <> lst2[i] then
      if (lst1[i] + 2) mod 2 = 0 then
        ex1 += 1
      else if (lst2[i] + 2) mod 2 = 0 then
        ex2 += 1
    else Result := 'NO';
  if (ex1 = 0) or (ex2 = 0) then
    exit
  ;
  Result := 'YES'
end;


function Histogram(test: string): Dictionary<string, integer>;
begin
  var s := test.Split(' ').Select(s -> s.ToLower).ToArray;
  var d := new Dictionary<string, integer>();
  foreach var x in s do
    if d.ContainsKey(x) then
      d[x] := d[x] + 1
    else d[x] := 1;
  var max := d.Values.Max;
  var res := new Dictionary<string, integer>();
  foreach var kv in d do
    if kv.Value = max then
      res.Add(kv.Key, max);
  Result := res;
end;


