function Minsubarraysum(nums: array of integer): integer;
begin
  Result := integer.MaxValue;
  for var i := 0 to nums.Length - 1 do
    for var j := i downto 0 do
    begin
      var sum := 0;
      for var k := j to i do
        sum += nums[k];
      Result := min(Result, sum);
    end;
end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var res := 0;
  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        res += capacity;
  Result := res div n;
end;


