function SelectWords(s: string; n: integer): array of string;
begin
  var result := [];
  var words := s.ToWords;
  foreach var w in words do
  begin
    var consonants := w.Count(x -> char.IsLower(x) and not char.IsLetter(x));
    if consonants = n then
      result.Add(w)
  end;
  Result := result
end;


function GetClosestVowel(word: string): string;
begin
  var n := word.Length;
  var vowels := 'aeiouAEIOU';
  var minDist := n + 1;
  var res := '';
  for var i := 1 to n - 1 do
  begin
    if (word[i] in vowels) and (word[i - 1] not in vowels) and (word[i + 1] not in vowels) then
    begin
      if word[i] < word[i - 1] then
        word[i - 1] := word[i];
      if word[i] > word[i + 1] then
        word[i + 1] := word[i];
      var dist := word[i + 1] - word[i - 1];
      if dist < minDist then
      begin
        minDist := dist;
        res := word[i];
      end;
    end;
  end;
  if minDist = n + 1 then
    result := ''
  else
    result := res;
end;


function MatchParens(lst: array of string): string;
begin
  var s := lst[0] + lst[1];
  var open_count := 0;
  foreach var c in s do
    if c = '(' then
      open_count += 1
    else if c = ')' then
      if open_count = 0 then
        break
      else open_count -= 1;
  Result := if open_count = 0 then 'Yes' else 'No';
end;


