  if m.Success then
  begin
    var mm := StrToInt(m[1].Value);
    var dd := StrToInt(m[2].Value);
    var yyyy := StrToInt(m[3].Value);
    Result := (mm > 0) and (mm <= 12) and (dd > 0) and (dd <= if mm = 2 then 29 else if mm = 4 then 30
        else if mm = 6 then 30 else if mm = 9 then 30 else 31)
        and (yyyy >= 0) and (yyyy <= CurrentYear) and (yyyy mod 4 = 0) and (yyyy mod 100 <> 0)
        and (yyyy mod 400 = 0);
    exit;
  end;
  Result := False;
end;


