function Tri(n: integer): array of real;
begin
  Result := new real[n + 1];
  Result[0] := 3;
  for var i := 1 to n do
    if i mod 2 = 0 then
      Result[i] := i div 2
    else Result[i] := Result[i - 1] + Result[i - 2] + Result[i + 1]
end;


