function CanArrange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var i := n - 1;
  while (i > 0) and (arr[i] >= arr[i - 1]) do
    i -= 1;
  if i = 0 then
    Result := -1
  else
  begin
    while (i > 0) and (arr[i - 1] > arr[i]) do
      arr[i - 1] := arr[i] + 1;
    Result := i - 1;
  end;
end;


