  if n mod 2 <> 0 then
    exit false;
  for var i := 1 to n do
    if i mod 2 = 0 then
      a := a + i
    else
      b := b + i;
  for var i := 1 to a do
    if i mod 2 <> 0 then
      c := c + i
    else
      d := d + i;
  Result := (n - a) = b and (n - a) = d
end;


