function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder(text);
  var i := 0;
  while i < sb.Length - 1 do
  begin
    if sb[i] = ' ' then
    begin
      sb[i] := '_';
      if sb[i + 1] = ' ' then
      begin
        sb.Remove(i + 1, 1);
      end
    end
    else if sb[i] = '  ' then
    begin
      sb.Remove(i, 1);
      if i > 0 then
        i := i - 1;
    end
  end;
  Result := sb.ToString;
end;


